export const booksControllerUpdateBodyNewSeriesTotalBooksMax = 999;

export const booksControllerUpdateBodyPagesCountMax = 10000;

export const booksControllerUpdateBodyPartNumberMax = 999;

export const booksControllerUpdateBodyPublicationYearMin = 1000;
export const booksControllerUpdateBodyPublicationYearMax = 2027;

export const booksControllerUpdateBodyPublisherIdRegExp = new RegExp(
  "^([0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-8][0-9a-fA-F]{3}-[89abAB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}|00000000-0000-0000-0000-000000000000|ffffffff-ffff-ffff-ffff-ffffffffffff)$",
);
export const booksControllerUpdateBodyPurchaseInfoExpectedPriceExclusiveMin = 0;
export const booksControllerUpdateBodyPurchaseInfoExpectedPriceMax = 99999999.99;

export const booksControllerUpdateBodyPurchaseInfoStoreUrlMax = 300;

export const booksControllerUpdateBodyReadingProgressAbandonedAtRegExp = new RegExp(
  "^(?:(?:\\d\\d[2468][048]|\\d\\d[13579][26]|\\d\\d0[48]|[02468][048]00|[13579][26]00)-02-29|\\d{4}-(?:(?:0[13578]|1[02])-(?:0[1-9]|[12]\\d|3[01])|(?:0[469]|11)-(?:0[1-9]|[12]\\d|30)|(?:02)-(?:0[1-9]|1\\d|2[0-8])))$",
);
export const booksControllerUpdateBodyReadingProgressCurrentPageMin = 0;
export const booksControllerUpdateBodyReadingProgressCurrentPageMax = 100000;

export const booksControllerUpdateBodyReadingProgressFinishedAtRegExp = new RegExp(
  "^(?:(?:\\d\\d[2468][048]|\\d\\d[13579][26]|\\d\\d0[48]|[02468][048]00|[13579][26]00)-02-29|\\d{4}-(?:(?:0[13578]|1[02])-(?:0[1-9]|[12]\\d|3[01])|(?:0[469]|11)-(?:0[1-9]|[12]\\d|30)|(?:02)-(?:0[1-9]|1\\d|2[0-8])))$",
);
export const booksControllerUpdateBodyReadingProgressPausedAtRegExp = new RegExp(
  "^(?:(?:\\d\\d[2468][048]|\\d\\d[13579][26]|\\d\\d0[48]|[02468][048]00|[13579][26]00)-02-29|\\d{4}-(?:(?:0[13578]|1[02])-(?:0[1-9]|[12]\\d|3[01])|(?:0[469]|11)-(?:0[1-9]|[12]\\d|30)|(?:02)-(?:0[1-9]|1\\d|2[0-8])))$",
);
export const booksControllerUpdateBodyReadingProgressRatingMin = 0.5;
export const booksControllerUpdateBodyReadingProgressRatingMax = 10;
export const booksControllerUpdateBodyReadingProgressRatingMultipleOf = 0.5;

export const booksControllerUpdateBodyReadingProgressStartedAtRegExp = new RegExp(
  "^(?:(?:\\d\\d[2468][048]|\\d\\d[13579][26]|\\d\\d0[48]|[02468][048]00|[13579][26]00)-02-29|\\d{4}-(?:(?:0[13578]|1[02])-(?:0[1-9]|[12]\\d|3[01])|(?:0[469]|11)-(?:0[1-9]|[12]\\d|30)|(?:02)-(?:0[1-9]|1\\d|2[0-8])))$",
);
export const booksControllerUpdateBodySeriesIdRegExp = new RegExp(
  "^([0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-8][0-9a-fA-F]{3}-[89abAB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}|00000000-0000-0000-0000-000000000000|ffffffff-ffff-ffff-ffff-ffffffffffff)$",
);
export const booksControllerUpdateBodyTagsMax = 12;

export const BooksControllerUpdateBody = zod.object({
  addToReadingQueue: zod.boolean().optional(),
  ageCategory: zod
    .enum([
      "not_specified",
      "no_restrictions",
      "6_plus",
      "12_plus",
      "14_plus",
      "16_plus",
      "18_plus",
    ])
    .optional(),
  authors: zod
    .array(
      zod.union([
        zod.object({
          id: zod.uuid().regex(booksControllerUpdateBodyAuthorsItemOneIdRegExp),
        }),
        zod.object({
          openLibraryKey: zod
            .string()
            .regex(booksControllerUpdateBodyAuthorsItemTwoOpenLibraryKeyRegExp),
        }),
        zod.object({
          name: zod.string(),
        }),
      ]),
    )
    .min(1)
    .max(booksControllerUpdateBodyAuthorsMax)
    .optional(),
  bookType: zod.enum(["solo", "series_part"]).optional(),
  coverMediaId: zod.uuid().regex(booksControllerUpdateBodyCoverMediaIdRegExp).nullish(),
  dedication: zod.string().nullish(),
  deliveryInfo: zod
    .object({
      currency: zod.enum(["UAH", "EUR", "USD"]).nullish(),
      deliveryService: zod.string().nullish(),
      deliveryStatus: zod.enum(["ordered", "in_transit", "ready_for_pickup"]).optional(),
      expectedDeliveryDate: zod.iso
        .date()
        .regex(booksControllerUpdateBodyDeliveryInfoExpectedDeliveryDateRegExp)
        .nullish(),
      note: zod.string().nullish(),
      orderDate: zod.iso
        .date()
        .regex(booksControllerUpdateBodyDeliveryInfoOrderDateRegExp)
        .nullish(),
      orderNumber: zod.string().nullish(),
      price: zod
        .number()
        .gt(booksControllerUpdateBodyDeliveryInfoPriceExclusiveMin)
        .max(booksControllerUpdateBodyDeliveryInfoPriceMax)
        .nullish(),
      storeName: zod.string().nullish(),
      trackingNumber: zod.string().nullish(),
      trackingUrl: zod.string().max(booksControllerUpdateBodyDeliveryInfoTrackingUrlMax).nullish(),
    })
    .optional(),
  description: zod.string().nullish(),
  formats: zod.array(zod.enum(["paper", "ebook", "audiobook"])).optional(),
  genres: zod
    .array(zod.string().min(1).max(booksControllerUpdateBodyGenresItemMax))
    .max(booksControllerUpdateBodyGenresMax)
    .optional(),
  illustrator: zod.string().nullish(),
  isbn: zod.string().nullish(),
  isFavorite: zod.boolean().optional(),
  language: zod
    .enum(["ukrainian", "english", "polish", "german", "french", "spanish", "other"])
    .optional(),
  listIds: zod
    .array(zod.uuid().regex(booksControllerUpdateBodyListIdsItemRegExp))
    .max(booksControllerUpdateBodyListIdsMax)
    .optional(),
  loanInfo: zod
    .object({
      expectedReturnDate: zod.iso
        .date()
        .regex(booksControllerUpdateBodyLoanInfoExpectedReturnDateRegExp)
        .nullish(),
      loanDate: zod.iso.date().regex(booksControllerUpdateBodyLoanInfoLoanDateRegExp).nullish(),
      note: zod.string().nullish(),
      personName: zod.string().optional(),
    })
    .optional(),
  newLists: zod
    .array(
      zod.object({
        description: zod.string().optional(),
        name: zod.string(),
      }),
    )
    .max(booksControllerUpdateBodyNewListsMax)
    .optional(),
  newSeries: zod
    .object({
      authors: zod
        .array(
          zod.union([
            zod.object({
              id: zod.uuid().regex(booksControllerUpdateBodyNewSeriesAuthorsItemOneIdRegExp),
            }),
            zod.object({
              openLibraryKey: zod
                .string()
                .regex(booksControllerUpdateBodyNewSeriesAuthorsItemTwoOpenLibraryKeyRegExp),
            }),
            zod.object({
              name: zod.string(),
            }),
          ]),
        )
        .max(booksControllerUpdateBodyNewSeriesAuthorsMax)
        .optional(),
      description: zod.string().optional(),
      genres: zod
        .array(zod.string().min(1).max(booksControllerUpdateBodyNewSeriesGenresItemMax))
        .max(booksControllerUpdateBodyNewSeriesGenresMax)
        .default(booksControllerUpdateBodyNewSeriesGenresDefault),
      name: zod.string(),
      status: zod
        .enum(["completed", "ongoing", "unknown"])
        .default(booksControllerUpdateBodyNewSeriesStatusDefault),
      totalBooks: zod
        .number()
        .min(1)
        .max(booksControllerUpdateBodyNewSeriesTotalBooksMax)
        .optional(),
    })
    .optional(),
  originalTitle: zod.string().nullish(),
  ownershipStatus: zod
    .enum([
      "none",
      "want_to_buy",
      "in_transit",
      "owned",
      "borrowed_from_someone",
      "lent_to_someone",
    ])
    .optional(),
  pagesCount: zod.number().min(1).max(booksControllerUpdateBodyPagesCountMax).nullish(),
  partNumber: zod.number().min(1).max(booksControllerUpdateBodyPartNumberMax).optional(),
  publicationYear: zod
    .number()
    .min(booksControllerUpdateBodyPublicationYearMin)
    .max(booksControllerUpdateBodyPublicationYearMax)
    .nullish(),
  publisherId: zod.uuid().regex(booksControllerUpdateBodyPublisherIdRegExp).optional(),
  publisherName: zod.string().optional(),
  purchaseInfo: zod
    .object({
      currency: zod.enum(["UAH", "EUR", "USD"]).nullish(),
      expectedPrice: zod
        .number()
        .gt(booksControllerUpdateBodyPurchaseInfoExpectedPriceExclusiveMin)
        .max(booksControllerUpdateBodyPurchaseInfoExpectedPriceMax)
        .nullish(),
      note: zod.string().nullish(),
      storeName: zod.string().nullish(),
      storeUrl: zod.string().max(booksControllerUpdateBodyPurchaseInfoStoreUrlMax).nullish(),
    })
    .optional(),
  queuePriority: zod.enum(["low", "normal", "high"]).optional(),
  readingProgress: zod
    .object({
      abandonedAt: zod.iso
        .date()
        .regex(booksControllerUpdateBodyReadingProgressAbandonedAtRegExp)
        .nullish(),
      currentPage: zod
        .number()
        .min(booksControllerUpdateBodyReadingProgressCurrentPageMin)
        .max(booksControllerUpdateBodyReadingProgressCurrentPageMax)
        .nullish(),
      finishedAt: zod.iso
        .date()
        .regex(booksControllerUpdateBodyReadingProgressFinishedAtRegExp)
        .nullish(),
      impression: zod.string().nullish(),
      note: zod.string().nullish(),
      pausedAt: zod.iso
        .date()
        .regex(booksControllerUpdateBodyReadingProgressPausedAtRegExp)
        .nullish(),
      rating: zod
        .number()
        .min(booksControllerUpdateBodyReadingProgressRatingMin)
        .max(booksControllerUpdateBodyReadingProgressRatingMax)
        .multipleOf(booksControllerUpdateBodyReadingProgressRatingMultipleOf)
        .nullish(),
      startedAt: zod.iso
        .date()
        .regex(booksControllerUpdateBodyReadingProgressStartedAtRegExp)
        .nullish(),
    })
    .optional(),
  readingStatus: zod
    .enum(["not_started", "want_to_read", "reading", "paused", "finished", "dnf", "rereading"])
    .optional(),
  seriesId: zod.uuid().regex(booksControllerUpdateBodySeriesIdRegExp).optional(),
  tags: zod.array(zod.string()).max(booksControllerUpdateBodyTagsMax).optional(),
  title: zod.string().optional(),
  translator: zod.string().nullish(),
});

